const RefreshMachineActivationCodeAggregate = `-- name: RefreshMachineActivationCodeAggregate :one
WITH cnt AS (
    SELECT
        COUNT(*)::int AS c
    FROM
        machine_activation_claims
    WHERE
        activation_code_id = $1
        AND result = 'succeeded'
)
UPDATE
    machine_activation_codes AS mac
SET
    uses = cnt.c,
    claimed_fingerprint_hash = $2,
    status = CASE
        WHEN cnt.c >= mac.max_uses THEN 'expired'::text
        ELSE mac.status
    END,
    updated_at = now()
FROM
    cnt
WHERE
    mac.id = $1
RETURNING
    mac.id, mac.machine_id, mac.code_hash, mac.max_uses, mac.uses, mac.expires_at, mac.notes, mac.status, mac.claimed_fingerprint_hash, mac.created_at, mac.updated_at
`

